from PIL import Image
from scipy.ndimage import binary_propagation
import numpy as np
from pathlib import Path
import base64,json
p=Path(__file__).parent;out=p/'derivees-pmd';out.mkdir(exist_ok=True)
def extract(name,box,scale,anchor=175):
 a=np.array(Image.open(p/'images'/name).convert('RGB')).astype('int16');bgcol=np.median(a[:25,:25].reshape(-1,3),axis=0);m=np.sqrt(((a-bgcol)**2).sum(axis=2))<35;seed=np.zeros(m.shape,bool);seed[0,:]=m[0,:];seed[-1,:]=m[-1,:];seed[:,0]=m[:,0];seed[:,-1]=m[:,-1];bg=binary_propagation(seed,mask=m,structure=np.ones((3,3)));im=Image.fromarray(np.dstack((a.astype('uint8'),np.where(bg,0,255).astype('uint8'))),'RGBA').crop(box);im=im.resize((round(im.width*scale),round(im.height*scale)),Image.Resampling.NEAREST);c=Image.new('RGBA',(200,200));c.alpha_composite(im,((200-im.width)//2,anchor-im.height));return c
for key,fn,box,scale in [
('idle1','reprise-face.png',(206,90,860,918),160/828),('idle2','pmd-idle-02.png',(206,90,860,918),160/828),
('atk1','pmd-attaque-anticipation.png',(206,90,860,918),160/828),('atk2','pmd-attaque-02-correct.png',(206,90,860,918),160/828),
('sleep1','pmd-sleep-01.png',(237,126,1001,771),135/645),('sleep2','pmd-sleep-02-correct.png',(237,126,1001,771),135/645)]:
 extract(fn,box,scale).save(out/(key+'.png'))
def data(f):return 'data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode()
assets={n:data(out/(n+'.png')) for n in ['idle1','idle2','atk1','atk2','sleep1','sleep2']}; refs={n:data(p/'refs-spritecollab'/(n+'-Anim.png')) for n in ['Idle','Sleep','Attack']}
t='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Animation PMD : référence et étude Méga-Tsareena</title><style>body{font:16px system-ui;color:#eaf2e4;background:#15221d;margin:0}main{max-width:1000px;margin:auto;padding:24px}h1{margin-bottom:6px}.muted{color:#b9ccb7}.columns{display:grid;grid-template-columns:1fr 1fr;gap:14px}.pane{background:#23372d;border:1px solid #4a6750;padding:14px;border-radius:16px;text-align:center}canvas{background:#cfdfc4;border-radius:10px;width:100%;max-width:360px;image-rendering:pixelated}.toolbar{margin:16px 0;display:flex;gap:8px;flex-wrap:wrap}button{padding:10px 15px;border-radius:9px;border:1px solid #759b78;background:#315342;color:white;font-weight:bold;cursor:pointer}button.active{background:#c4e293;color:#14281a}.note{padding:14px 18px;background:#2a372b;border-radius:12px;margin:16px 0}a{color:#d0f399}li{line-height:1.55}@media(max-width:600px){.columns{grid-template-columns:1fr}}</style></head><body><main><h1>Reprendre les animations PMD</h1><p class="muted">Comparaison directe des planches de Tsareena et d’un premier essai Méga-Tsareena, de face.</p><div class="toolbar"><button data-id="Idle">Repos</button><button data-id="Sleep">Sommeil</button><button data-id="Attack">Attaque · rejouer</button></div><div class="columns"><div class="pane"><h2>Tsareena · référence</h2><canvas id="ref" width="200" height="200"></canvas><p class="muted" id="reftxt"></p></div><div class="pane"><h2>Méga-Tsareena · étude</h2><canvas id="mega" width="200" height="200"></canvas><p class="muted" id="megatxt"></p></div></div><div class="note"><strong>Ce que montre cet essai :</strong> deux images originales générées pour le repos et deux pour le sommeil, sans effet fantaisiste. L’attaque est un <strong>blocage provisoire</strong> : deux dessins de robe plus la pose de repos, déplacés selon la trajectoire observée sur la référence ; ce ne sont pas 14 dessins originaux. Le passage repos-sommeil n’est pas encore animé. Les images brutes ont été conservées ; les copies d’aperçu sont détourées et redimensionnées.</div><h2>Vérification SpriteCollab</h2><ul><li>Repos : 2 images, 30 + 30 ticks ; sommeil : 2 images, 30 + 35 ticks, une seule direction dans la planche de Tsareena.</li><li>Attaque : 14 images, durées 4, 2, 2, 2, 2, 2, 2, 3, 1, 1, 2, 2, 2, 2 ticks ; phase de retour après l’impact. Un tick = 1/60 s.</li><li>Restent à dessiner et raccorder : toutes les images uniques d’attaque, les autres directions, les actions manquantes, les ombres et les offsets ; ceci n’est pas un pack prêt pour SpriteCollab.</li></ul><p class="muted">Référence : <a href="https://github.com/PMDCollab/SpriteCollab/tree/master/sprite/0763">SpriteCollab, Tsareena #0763</a> · crédit du sprite : baronessfaron.</p></main><script>
const raw=__DATA__,refImgs={},megaImgs={};for(const [k,v] of Object.entries(raw.refs)){let im=new Image();im.src=v;refImgs[k]=im}for(const [k,v] of Object.entries(raw.assets)){let im=new Image();im.src=v;megaImgs[k]=im}
const cfg={Idle:{w:32,h:56,d:[30,30]},Sleep:{w:32,h:40,d:[30,35]},Attack:{w:72,h:88,d:[4,2,2,2,2,2,2,3,1,1,2,2,2,2]}},xs=[0,-1,-1,0,-1,0,-1,2,2,2,3,2,-1,-1],ys=[0,-1,-2,-2,-2,-2,-2,1,9,16,16,16,11,6];let current='Idle',start=performance.now();const rc=document.querySelector('#ref').getContext('2d'),mc=document.querySelector('#mega').getContext('2d');rc.imageSmoothingEnabled=false;mc.imageSmoothingEnabled=false;function select(n){current=n;start=performance.now();document.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.id===n));document.querySelector('#reftxt').textContent=n==='Attack'?'14 images de la planche originale':'Boucle des deux images originales';document.querySelector('#megatxt').textContent=n==='Attack'?'Prototype : poses répétées et déplacement, pas encore 14 dessins':'Deux images générées, en boucle'}document.querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.id));function frame(t){let c=cfg[current],total=c.d.reduce((a,b)=>a+b,0),ticks=Math.floor((t-start)*60/1000);if(current==='Attack'&&ticks>=total){select('Idle');c=cfg.Idle;ticks=0}ticks%=total;let i=0;while(ticks>=c.d[i]){ticks-=c.d[i];i++}rc.clearRect(0,0,200,200);mc.clearRect(0,0,200,200);let r=refImgs[current];if(r.complete&&r.naturalWidth){let k=4;rc.drawImage(r,i*c.w,0,c.w,c.h,100-c.w*k/2,175-(current==='Sleep'?29:current==='Attack'?50:34)*k,c.w*k,c.h*k)}let key=current==='Idle'?(i?'idle2':'idle1'):current==='Sleep'?(i?'sleep2':'sleep1'):(i<2||i>12?'idle1':i%2?'atk1':'atk2'),m=megaImgs[key],dx=current==='Attack'?xs[i]*2:0,dy=current==='Attack'?ys[i]*2:0;if(m.complete&&m.naturalWidth)mc.drawImage(m,dx,dy);requestAnimationFrame(frame)}select('Idle');requestAnimationFrame(frame);
</script></body></html>'''
(p/'Etude-animation-SpriteCollab.html').write_text(t.replace('__DATA__',json.dumps({'assets':assets,'refs':refs},separators=(',',':'))),encoding='utf8')
